{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Vol Desk Data",
    "url": "http://localhost:7801",
    "widgets_json": {
      "vix_history": {
        "name": "VIX History",
        "description": "Daily CBOE VIX closes with returns.",
        "endpoint": "/vix-history",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "window",
            "type": "number",
            "label": "Window",
            "value": 30,
            "min": 5,
            "max": 365
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "date",
                "headerName": "Date",
                "cellDataType": "dateString"
              },
              {
                "field": "close",
                "headerName": "Close",
                "cellDataType": "number"
              },
              {
                "field": "return_pct",
                "headerName": "Return %",
                "cellDataType": "number",
                "formatterFn": "percent",
                "renderFn": "greenRed"
              }
            ]
          }
        }
      }
    }
  }
}
